function refSpells(p) {
  p.appendChild(el("h3", {}, "Spells"));

  // ----- How spellcasting works -----
  const how = el("div", { class: "rules-sec" });
  how.appendChild(el("h4", { class: "rule-h" }, "How spellcasting works"));
  [
    "Only spellcasting professions cast spells — the Wizard (memorize up to 3), the Ranger (memorize 1), and anyone wielding the Archmage's Staff (+1). Other classes may still use single-shot Spell Scrolls if their profession allows scrolls.",
    "Your spell book holds every spell you've learned, but you can only cast spells you currently have memorized. Swapping memorized spells normally happens between dungeons; the Wizard's Spell Recall ability swaps one mid-combat.",
    "Casting costs Action Points (AP). Your Max AP = 2 × Willpower, and current AP can never drop below 0 or rise above Max AP. After fully exploring a room you restore AP equal to your Willpower — but not if you flee.",
    "Combat spells make a combat roll: d6 + Willpower + the spell's Hit (H). If that total is greater than or equal to the target's Defense it hits, dealing damage equal to the spell's Damage (D). The target must be within the spell's Range (R) and in line of sight. Willpower is always the attack skill for spells, never Strength or Agility.",
    "Non-combat spells (utility, buffs, control) need no roll — just pay the AP and apply the listed effect.",
    "Spells marked AP \"varies\" scale with what you spend (e.g. +1 attribute per AP). Spend only what you can afford from current AP.",
    "Bonus Rating improves each new combat spell you learn by +1 to Range, Damage, and/or Hit per rating — it does not change non-combat spells or spells you already had when the rating went up.",
  ].forEach((line) => how.appendChild(el("p", { class: "rule-p" }, line)));
  p.appendChild(how);

  // ----- What the values mean -----
  const legendSec = el("div", { class: "rules-sec" });
  legendSec.appendChild(el("h4", { class: "rule-h" }, "What the values mean"));
  const dl = el("div", { class: "rule-dl" });
  [
    ["AP", "Action Point cost to cast. \"varies\" means the effect scales with how much AP you spend."],
    ["Combat", "Combat spells need an attack roll and show R/D/H; \"—\" means it's a non-combat spell that just takes effect."],
    ["R — Range", "How many squares away the target can be (line of sight still required)."],
    ["D — Damage", "HP the target loses on a hit."],
    ["H — Hit", "Added to your d6 + Willpower combat roll to land the spell."],
  ].forEach(([t, d]) => dl.appendChild(el("div", { class: "rule-dt" },
    el("span", { class: "term" }, t), el("span", {}, " — " + d))));
  legendSec.appendChild(dl);
  p.appendChild(legendSec);

  // ----- Spell list -----
  p.appendChild(el("h4", { class: "rule-h" }, "Spell list"));
  const t = el("table", { class: "ref" }, el("tr", {}, el("th", {}, "Spell"), el("th", {}, "AP"), el("th", {}, "Combat (R/D/H)"), el("th", {}, "Effect")));
  G.spells.forEach((s) => t.appendChild(el("tr", {}, el("td", {}, s.name), el("td", { class: "mono" }, apLabel(s.ap)),
    el("td", { class: "mono" }, s.combat ? `R${s.R} D${s.D} H${s.H}` : "—"), el("td", {}, s.text))));
  p.appendChild(t);
}

