// Armor mitigates ONCE per round, not once per hit (Pocket Dungeon rules). Each
// monster attacks on its own, so we track a per-round armor pool that depletes
// across the round's strikes — mathematically identical to summing the round's
// hits and subtracting armor once. The pool resets each round.
function ensureMonsterPhase(d) {
  if (!d.mphase || d.mphase.round !== d.round) {
    d.mphase = { round: d.round, armorLeft: heroArmorValue() };
  }
  return d.mphase;
}

// A single monster attacks the hero. Not every monster can act each round (range,
// knocked down, etc.), so this is triggered per-monster by the player.
function monsterStrike(mon) {
  const d = state.dungeon, h = state.hero;
  if (mon.hp <= 0) return;
  if (mon.struckRound === d.round &&
      !confirm(`${mon.label} has already attacked this round. Attack again anyway?`)) return;
  const ph = ensureMonsterPhase(d);
  const r = roll(6);
  const hit = r >= mon.att[0] && r <= mon.att[1];
  mon.struckRound = d.round;
  if (!hit) {
    logMsg(`${mon.label} attacks: d6=${r} (Att${mon.att[0]}-${mon.att[1]}) — miss.`, "hit");
    render(); saveNow(); return;
  }
  const raw = mon.D;
  const absorbed = Math.min(ph.armorLeft, raw);
  const net = raw - absorbed;
  ph.armorLeft -= absorbed;
  h.hp -= net;
  logMsg(`${mon.label} attacks: d6=${r} HIT — ${raw} dmg${absorbed ? ` − ${absorbed} armor` : ""} = ${net} HP lost.` +
    (mon.special ? `  (Check special: ${mon.special})` : ""), net > 0 ? "miss" : "hit");
  if (h.hp <= 0) { h.hp = 0; return heroDies(); }
  render(); saveNow();
}

// Convenience: every standing monster that hasn't gone yet this round attacks.
function allMonstersStrike() {
  const d = state.dungeon;
  const pending = d.currentRoom.monsters.filter((m) => m.hp > 0 && m.struckRound !== d.round);
  if (!pending.length) { alert("Every standing monster has already attacked this round."); return; }
  pending.forEach((m) => { if (state.hero.hp > 0) monsterStrike(m); });
}

// Refresh the armor pool and advance to the next round.
function endMonsterRound() {
  const d = state.dungeon;
  if (!d.currentRoom.monsters.some((m) => m.hp > 0)) { alert("No monsters left — the encounter is clear."); return; }
  d.round += 1;
  d.mphase = null;
  logMsg(`— Round ${d.round} —`, "");
  render(); saveNow();
}

