input.new_string:
function castCombatSpell(spellName, monster) {
  const h = state.hero;
  const s = G.spells.find((x) => x.name === spellName);
  // AP cost: fixed for most spells, player-chosen for "varies" spells (e.g. Life Drain).
  let cost;
  if (s.ap === "varies") {
    const input = prompt(`How much AP to spend on ${s.name}? (you have ${h.ap})`, String(Math.min(2, h.ap)));
    if (input === null) return;                        // cancelled
    cost = parseInt(input, 10);
    if (isNaN(cost) || cost < 1) { alert("Enter a positive amount of AP."); return; }
  } else {
    cost = s.ap || 0;
  }
  if (cost > h.ap) { alert(`Not enough AP for ${s.name}: need ${cost}, have ${h.ap}.`); return; }
  h.ap -= cost;                                        // AP is spent whether the spell hits or misses
  const apTag = cost ? ` [−${cost} AP]` : "";
  const r = roll(6);
  const total = r + h.wil + (s.H || 0);
  const dmg = (s.D || 0) + (s.brD || 0);
  if (total >= monster.Def) {
    monster.hp -= dmg;
    let extra = "";
    if (s.name === "Life Drain") {                     // heal 1 HP per 2 AP spent
      const heal = Math.floor(cost / 2);
      if (heal > 0) { const before = h.hp; h.hp = Math.min(h.maxhp, h.hp + heal); extra = `, healed ${h.hp - before}`; }
    }
    logMsg(`${s.name}: d6=${r} +Wil${h.wil} +H${s.H||0} = ${total} vs Def${monster.Def} — HIT, ${dmg} dmg to ${monster.label}${extra}.${apTag}`, "hit");
    if (monster.hp <= 0) killMonster(monster);
  } else {
    logMsg(`${s.name}: d6=${r} +Wil${h.wil} +H${s.H||0} = ${total} vs Def${monster.Def} — miss on ${monster.label}.${apTag}`, "miss");
  }
  render();
  saveNow();
}

