// spent, or null if the cast should be aborted (cancelled, or not enough AP — a
// transient toast explains why). "varies" spells prompt for the amount to spend.
function spendSpellAP(s) {
  const h = state.hero;
  let cost;
  if (s.ap === "varies") {
    const input = prompt(`How much AP to spend on ${s.name}? (you have ${h.ap})`, String(Math.min(2, h.ap)));
    if (input === null) return null;                   // cancelled
    cost = parseInt(input, 10);
    if (isNaN(cost) || cost < 1) { toast("Enter a positive amount of AP.", "err"); return null; }
  } else {
    cost = s.ap || 0;
  }
  if (cost > h.ap) { toast(`Not enough AP for ${s.name} — need ${cost}, have ${h.ap}.`, "err"); return null; }
