      el("button", { class: "btn sm", style: "align-self:center",
        title: passive ? `Apply ${a.name}` : `Use ${a.name} (−${cost} AP)`,
        onclick: () => useAbility(a) }, passive ? "Apply" : "Use")));
  });
  return box;
}

// Activate a profession ability. Effects that adjust the board/combat are logged
// for the player to apply by hand; the two clean HP/AP effects are auto-applied.
function useAbility(a) {
  const h = state.hero;
  if (a.name === "Dark Rituals") {                       // sacrifice 4 HP to recover 4 AP
    if (h.hp <= 4) { toast("Dark Rituals needs more than 4 HP to sacrifice.", "err"); return; }
    h.hp -= 4;
    const before = h.ap; h.ap = Math.min(h.maxap, h.ap + 4);
    logMsg(`Dark Rituals: sacrificed 4 HP to recover ${h.ap - before} AP.`, "gold");
    toast(`Dark Rituals · −4 HP, +${h.ap - before} AP`, "ok");
    render(); saveNow(); return;
  }
  const cost = spendSpellAP(a);                          // shared AP-cost logic (handles "varies" + affordability)
  if (cost === null) return;
  if (a.name === "Heal") {                               // restore 1 HP
    const before = h.hp; h.hp = Math.min(h.maxhp, h.hp + 1);
    logMsg(`Heal [−${cost} AP]: restored ${h.hp - before} HP.`, "hit");
    toast(`Heal · −${cost} AP, +${h.hp - before} HP`, "ok");
  } else {
    logMsg(`Used ${a.name}${cost ? ` [−${cost} AP]` : ""} — ${a.text}`, "gold");
    toast(`${a.name}${cost ? ` · −${cost} AP` : ""}`, "ok");
  }
  render(); saveNow();
}

