function learnSpellModal(idx, count, sourceName) {
  const h = state.hero;
  const available = G.spells.map((s) => s.name).filter((n) => !h.spellbook.includes(n));
  const picks = [];
  const builder = () => {
    if (!available.length) {
      return el("div", {}, el("h2", {}, sourceName),
        el("div", { class: "note" }, "You already know every spell in the game — nothing left to learn."),
        el("div", { class: "btn-row" }, el("button", { class: "btn", onclick: closeModal }, "Close")));
    }
    const list = el("div", { style: "max-height:320px;overflow:auto;margin:8px 0" });
    available.forEach((n) => {
      const s = G.spells.find((x) => x.name === n);
      list.appendChild(el("label", { class: "spell-pick", style: "cursor:pointer;align-items:center" },
        el("input", { type: "checkbox", style: "width:auto", ...(picks.includes(n) ? { checked: "" } : {}),
          onchange: (e) => {
            if (e.target.checked) {
              if (picks.length >= count) { e.target.checked = false; toast(`This ${sourceName.toLowerCase()} adds ${count} spell${count === 1 ? "" : "s"}.`, "err"); return; }
              picks.push(n);
