          el("span", { class: "sub" }, `  ${apLabel(s.ap)} AP${s.combat ? ` · R${s.R} D${s.D} H${s.H}` : ""}`))));
    });
    return el("div", {},
      el("h2", {}, sourceName),
      el("div", { class: "note" }, `Add ${count === 1 ? "any one spell" : `any ${count} spells`} from the Spells table to your spell book.  (${picks.length}/${count} chosen)`),
      list,
      el("div", { class: "btn-row" },
        el("button", { class: "btn primary", disabled: picks.length ? null : "", onclick: () => confirmLearn(idx, picks.slice(), sourceName) }, "Add to spell book"),
        el("button", { class: "btn", onclick: closeModal }, "Cancel")));
  };
  showModal(builder);
}
