function heroArmorValue() {
  const h = state.hero;
  let a = (h.equipped.armor?.A || 0) + (h.equipped.armor?.brA || 0);
  a += (h.equipped.shield?.A || 0) + (h.equipped.shield?.brA || 0);
  a += (h.buffArmor || 0);                                // temporary armor from scrolls (e.g. Stoneskin)
  return a;
}

/* ----- timed buffs (Stoneskin, Innervate, …) ----- */
// Apply a buff's stat changes and record it so they can be reversed when it ends.
// mods: { str, agi, wil, armor, maxhp }. Duration is tracked in "turns" (combat rounds).
function applyBuff(name, mods, turns) {
  const h = state.hero;
  h.buffs = h.buffs || [];
  if (mods.str)   h.str += mods.str;
  if (mods.agi)   h.agi += mods.agi;
  if (mods.wil)   h.wil += mods.wil;
  if (mods.armor) h.buffArmor = (h.buffArmor || 0) + mods.armor;
  if (mods.maxhp) { h.maxhp += mods.maxhp; h.hp += mods.maxhp; }   // raise the ceiling and fill it
  h.maxap = deriveMaxAP(h);
  h.buffs.push({ id: (h._buffId = (h._buffId || 0) + 1), name, mods, turns });
}
function reverseBuff(b) {
  const h = state.hero, m = b.mods;
  if (m.str)   h.str -= m.str;
  if (m.agi)   h.agi -= m.agi;
  if (m.wil)   h.wil -= m.wil;
  if (m.armor) h.buffArmor = (h.buffArmor || 0) - m.armor;
  if (m.maxhp) { h.maxhp -= m.maxhp; if (h.hp > h.maxhp) h.hp = h.maxhp; }   // lose the temp buffer
  h.maxap = deriveMaxAP(h);
  if (h.ap > h.maxap) h.ap = h.maxap;
}
function endBuff(id) {
  const h = state.hero;
  const i = (h.buffs || []).findIndex((b) => b.id === id);
  if (i < 0) return;
