function mapCell(key, val, tokenMons, heroHere) {
  const cls = ["cell"];
  const kids = [];
  let title;
  if (tokenMons && tokenMons.length) {                      // one or more linked monsters stand here
    cls.push("token-mon");
    if (tokenMons.length === 1) {
      const m = tokenMons[0];
      if (m.boss) cls.push("boss");
      kids.push(el("span", { class: "tok-tag" }, monTag(m)));
      kids.push(el("span", { class: "tok-hp" }, String(m.hp)));
      title = `${m.label} — ${m.hp}/${m.hpMax} HP`;
    } else {                                                // a stack — show the count
      cls.push("stack");
      kids.push(el("span", { class: "tok-tag" }, "×" + tokenMons.length));
      title = tokenMons.map((m) => `${m.label} ${m.hp}/${m.hpMax}`).join(", ");
    }
  }
  else if (heroHere) { cls.push("hero"); kids.push("🛡"); title = "Your hero"; }  // the single hero token
  else if (val === "floor") cls.push("floor");
  else if (val === "monster") { cls.push("monster"); kids.push("👹"); }
  else if (val && val.indexOf("treasure") === 0) {
    cls.push("treasure"); kids.push("📦");
    if (val === "treasure-L") { cls.push("locked"); kids.push(el("span", { class: "lock-badge locked" }, "🔒")); }
    else if (val === "treasure-T") { cls.push("trapped"); kids.push(el("span", { class: "lock-badge trapped" }, "⚠")); }
  }
  else if (/^\d+$/.test(val)) { cls.push("floor", "explored"); kids.push(val); }
  const placing = placingMonsterUid !== null;
  if (placing) cls.push("placing");
  if (placing || !isEdgeTool()) cls.push("clickable");
  return el("div", {
    class: cls.join(" "),
    title,
    onclick: () => { if (placing) placeMonsterToken(key); else if (!isEdgeTool()) paintCell(key); },
  }, ...kids);
}

// pin (or move/remove) the monster awaiting placement onto a board square.
// Monsters may stack on a square (rules allow any number on a non-adjacent square).
function placeMonsterToken(key) {
  const r = state.dungeon.currentRoom;
  if (!r || placingMonsterUid === null) return;
  r.tokens = r.tokens || {};
  const uid = placingMonsterUid;
  if (r.tokens[uid] === key) delete r.tokens[uid];          // click its own square again -> remove
  else r.tokens[uid] = key;                                 // stacking allowed
  placingMonsterUid = null;
  render(); saveNow();
}

