// Manhattan distance in squares between two "row,col" cell keys. R1 = orthogonally
// adjacent (distance 1); diagonals are distance 2, so they're out of melee range.
function cellDist(a, b) {
  const [ar, ac] = a.split(",").map(Number);
  const [br, bc] = b.split(",").map(Number);
  return Math.abs(ar - br) + Math.abs(ac - bc);
}

// Convenience: every standing monster that is IN RANGE of the hero and hasn't gone
// yet this round attacks. Range is judged from placed board tokens vs each monster's
// R; monsters that are out of range, or have no token placed, are left for you to
// handle with their own 👹 Strike button.
function allMonstersStrike() {
  const d = state.dungeon, h = state.hero, r = d.currentRoom;
  const pending = r.monsters.filter((m) => m.hp > 0 && m.struckRound !== d.round);
  if (!pending.length) { alert("Every standing monster has already attacked this round."); return; }
  const heroCell = d.map.hero;
  if (!heroCell) {                                        // no hero token → range is unknowable
    if (!confirm("No hero token is placed, so the app can't tell who's in range. Have all remaining standing monsters attack anyway?")) return;
    pending.forEach((m) => { if (h.hp > 0) monsterStrike(m); });
    return;
  }
  const inRange = [], outRange = [], noToken = [];
  pending.forEach((m) => {
    const c = r.tokens?.[m.uid];
    if (!c) noToken.push(m.label);
    else if (cellDist(heroCell, c) <= (m.R || 1)) inRange.push(m);
    else outRange.push(m.label);
  });
  inRange.forEach((m) => { if (h.hp > 0) monsterStrike(m); });
  if (outRange.length) logMsg(`Out of range — did not attack: ${outRange.join(", ")}.`, "");
  if (noToken.length) logMsg(`No board token placed (range unknown) — use the 👹 Strike button for: ${noToken.join(", ")}.`, "");
  if (!inRange.length) toast(outRange.length || noToken.length ? "No monster is in range of the hero." : "No monster to attack.", "err");
}

