// Prompt the player to choose one living monster in the current room.
function pickAliveMonster(promptText) {
  const r = state.dungeon?.currentRoom;
  const alive = r ? r.monsters.filter((m) => m.hp > 0) : [];
  if (!alive.length) { toast("No monsters to target.", "err"); return null; }
  if (alive.length === 1) return alive[0];
  const list = alive.map((m, i) => `${i + 1}. ${m.label} (${m.hp}/${m.hpMax})`).join("\n");
  const input = prompt(`${promptText}\n${list}\n\nEnter a number:`, "1");
  if (input === null) return null;
  const i = parseInt(input, 10) - 1;
  if (isNaN(i) || i < 0 || i >= alive.length) { toast("Invalid choice.", "err"); return null; }
  return alive[i];
}

