// One-time migration: pull a room's old per-room chests into the persistent store.
function ensureChests() {
  const d = state.dungeon;
  if (!d || !d.active) return;
  if (!d.chests) {
    d.chests = []; d.nextChestId = 0;
    const r = d.currentRoom;
    if (r && Array.isArray(r.chests)) {
      r.chests.forEach((c) => d.chests.push({ id: d.nextChestId++, status: c.status, opened: !!c.opened, roomNum: r.roomNum, cell: null }));
      delete r.chests;
    }
  }
}

// Open a persistent chest by id (works for any room — even ones you've left).
function openChestById(id) {
  const d = state.dungeon, h = state.hero;
  const c = (d.chests || []).find((x) => x.id === id);
  if (!c || c.opened) return;
  breakEtherealLink("opened a chest");
  if (c.status === "Locked" && !confirm("This chest is Locked. Open it anyway (assumes you used an ability/item/spell)?")) return;
  if (c.status === "Trapped") {
    if (!confirm("This chest is Trapped — opening it deals 1 HP that cannot be mitigated. Open it?")) return;
    h.hp -= 1; logMsg("Trapped chest! −1 HP (cannot be mitigated).", "miss");
    if (h.hp <= 0) { h.hp = 0; c.opened = true; render(); saveNow(); return heroDies(); }
  }
  c.opened = true;
  logMsg(`Opened a ${c.status.toLowerCase()} chest (room ${c.roomNum}).`, "gold");
  rollTreasureItem();   // rolls treasure, then renders + saves
}

// Pin (or move/lift) the chest awaiting placement onto a board square.
function placeChestToken(key) {
  const c = (state.dungeon.chests || []).find((x) => x.id === placingChestId);
  if (!c) { placingChestId = null; return; }
  c.cell = (c.cell === key) ? null : key;   // click its own square again -> lift it off
  placingChestId = null;
  render(); saveNow();
}

