  h.pendingSpellDmg = 0; h.pendingHeighten = null;       // both consumed by this spell (hit or miss)
  const effH = (s.H || 0) * (heighten === "hit" ? 2 : 1); // Heighten doubles the Hit value (every missile)
  const hTag = heighten === "hit" ? " (Heightened Hit)" : heighten === "range" ? "  (Range doubled — adjudicate targeting)" : "";
  const shots = s.missiles || 1;                          // Magic Missile fires 2

