// Choose a target for a follow-up missile (defaults to the same monster).
function pickMissileTarget(defaultMon, promptText) {
  const r = state.dungeon?.currentRoom;
  const alive = r ? r.monsters.filter((m) => m.hp > 0) : [];
  if (!alive.length) return null;
  if (alive.length === 1) return alive[0];
  const defIdx = Math.max(0, alive.indexOf(defaultMon));
  const list = alive.map((m, i) => `${i + 1}. ${m.label} (${m.hp}/${m.hpMax})`).join("\n");
  const input = prompt(`${promptText}\n${list}\n\nEnter a number (Cancel = same target):`, String(defIdx + 1));
  if (input === null) return alive[defIdx];              // cancel → keep the default target
  const i = parseInt(input, 10) - 1;
  return (!isNaN(i) && i >= 0 && i < alive.length) ? alive[i] : alive[defIdx];
}

