// One-time migration: pull a room's old per-room chests & special into the persistent stores.
function ensureChests() {
  const d = state.dungeon;
  if (!d || !d.active) return;
  if (!d.chests) {
    d.chests = []; d.nextChestId = 0;
    const r = d.currentRoom;
    if (r && Array.isArray(r.chests)) {
      r.chests.forEach((c) => d.chests.push({ id: d.nextChestId++, status: c.status, opened: !!c.opened, roomNum: r.roomNum, cell: null }));
      delete r.chests;
    }
  }
  if (!d.features) {
    d.features = []; d.nextFeatureId = 0;
    const r = d.currentRoom;
    if (r && r.special) d.features.push({ id: d.nextFeatureId++, name: r.special.name, text: r.special.text, usesLeft: featureUses(r.special.name), roomNum: r.roomNum, cell: null });
  }
}

// Apply a special feature's effect (no render/save — the caller handles that).
function applySpecialEffect(name) {
  const h = state.hero;
  const fx = {
    "Healing Font": () => { h.hp = h.maxhp; logMsg("Healing Font: HP restored to max.", "hit"); },
    "Altar of Blessing": () => { h.bonusRatingBase = (h.bonusRatingBase || 0) + 1; recomputeBonusRating(); logMsg("Altar of Blessing: +1 Bonus Rating.", "gold"); },
    "Armory": () => { equipRoll(G.weapons, 8, "weapon"); equipRoll(G.armor, 6, null); equipRoll(G.exoticWeapons, 6, "weapon", true); },
    "Alchemy Lab": () => { for (let i = 0; i < 3; i++) { const p = pickByRange(G.potions, roll(8)); pushItem({ kind: "potion", name: p.name, text: p.text }); } },
    "Library": () => { for (let i = 0; i < 3; i++) { const s = pickByRange(G.scrolls, roll(8)); pushItem({ kind: "scroll", name: s.name, text: s.text }); } },
    "Arcane Forge": () => { for (let i = 0; i < 2; i++) { const mi = pickByRange(G.magicItems, roll(8)); pushItem({ kind: "magic", name: mi.name, text: mi.text, ...mi }); } },
  };
  (fx[name] || (() => {}))();
}

// Use a persistent special feature by id (works from any room). Spent ones are removed.
function useFeature(id) {
  const d = state.dungeon;
  const f = (d.features || []).find((x) => x.id === id);
  if (!f || f.usesLeft <= 0) return;
  breakEtherealLink(`used the ${f.name}`);
  applySpecialEffect(f.name);
  f.usesLeft -= 1;
  if (f.usesLeft > 0) logMsg(`${f.name}: ${f.usesLeft} use${f.usesLeft === 1 ? "" : "s"} left.`, "");
  else { d.features = d.features.filter((x) => x.id !== id); logMsg(`${f.name} is spent.`, "miss"); }
  render(); saveNow();
}

// Pin (or move/lift) the special feature awaiting placement onto a board square.
function placeFeatureToken(key) {
  const f = (state.dungeon.features || []).find((x) => x.id === placingFeatureId);
  if (!f) { placingFeatureId = null; return; }
  f.cell = (f.cell === key) ? null : key;
  placingFeatureId = null;
  render(); saveNow();
}

