// Unstable Potion: quaff & roll d6 for a random permanent effect.
function unstablePotion() {
  const h = state.hero;
  const r = roll(6);
  let msg, cls = "hit";
  if (r === 1) { h.str += 1; msg = "+1 Strength"; }
  else if (r === 2) { h.agi += 1; msg = "+1 Agility"; }
  else if (r === 3) { h.wil += 1; h.maxap = deriveMaxAP(h); msg = "+1 Willpower"; }
  else if (r === 4) { h.maxhp += 3; h.hp += 3; msg = "+3 Max HP"; }
  else if (r === 5) { msg = "nothing happens"; cls = ""; }
  else {                                                  // 6 → −1 to the highest attribute
    const stats = [["Strength", "str"], ["Agility", "agi"], ["Willpower", "wil"]];
    let best = stats[0];
    stats.forEach((s) => { if (h[s[1]] > h[best[1]]) best = s; });
    h[best[1]] = Math.max(0, h[best[1]] - 1);
    if (best[1] === "wil") { h.maxap = deriveMaxAP(h); if (h.ap > h.maxap) h.ap = h.maxap; }
    msg = `−1 ${best[0]} (your highest attribute)`; cls = "miss";
  }
  logMsg(`Unstable Potion: rolled d6=${r} → ${msg}.`, cls);
