function usePotion(idx) {
  const h = state.hero, it = h.inventory[idx], name = it.name;
  breakEtherealLink("used an item");
  let consume = true;
  if (/Healing/.test(name)) { h.hp = Math.min(h.maxhp, h.hp + 4); logMsg("Drank Potion of Healing (+4 HP).", "hit"); }
  else if (/Restoration/.test(name)) { h.ap = h.maxap; logMsg("Drank Potion of Restoration (AP full).", "hit"); }
  else if (/Unstable/.test(name)) { unstablePotion(); }
  else if (/Ignite|Explodify/.test(name)) { consume = throwPotion(name); }
  else if (/Vial of Acid/.test(name)) { consume = useVialOfAcid(); }
  else { logMsg(`Used ${name}.`, ""); }
  if (consume) h.inventory.splice(idx, 1);
  render(); saveNow();
}

// Thrown attack potions (Ignite = single target; Explodify = blast). Returns true if used.
function throwPotion(name) {
  const d = state.dungeon, h = state.hero, r = d?.currentRoom;
  const alive = r ? r.monsters.filter((m) => m.hp > 0) : [];
  if (!alive.length) { toast("No enemy to target.", "err"); return false; }

  if (/Ignite/.test(name)) {                              // auto-hit D3 to one enemy
    const target = alive.length === 1 ? alive[0] : pickAliveMonster("Potion of Ignite — target?");
    if (!target) return false;
    logMsg(`Potion of Ignite: auto-hits ${target.label} for 3.`, "hit");
    applyDamageToMon(target, 3);
    return true;
  }

  // Explodify: D3 to all enemies in the target square, D2 to each adjacent creature (incl. you!)
  const center = alive.length === 1 ? alive[0] : pickAliveMonster("Potion of Explodify — pick the enemy at the blast's center square");
  if (!center) return false;
  const centerCell = r.tokens?.[center.uid], heroCell = d.map.hero;
  logMsg(`Potion of Explodify thrown at ${center.label}'s square.`, "hit");
  if (centerCell) {                                       // token-aware: resolve square + splash automatically
    alive.forEach((m) => {
      const c = r.tokens?.[m.uid];
      if (!c) return;
      if (c === centerCell) applyDamageToMon(m, 3);       // in the square
      else if (cellDist(centerCell, c) === 1) applyDamageToMon(m, 2);  // orthogonally adjacent
    });
    if (heroCell && cellDist(centerCell, heroCell) === 1) {
      h.hp -= 2; logMsg("Explodify caught you in the blast: −2 HP!", "miss");
      if (h.hp <= 0) { h.hp = 0; return heroDies(), true; }
    }
  } else {                                                // no token for the center → resolve the center, prompt the rest
    applyDamageToMon(center, 3);
    toast("Place tokens to auto-resolve the D2 splash — apply it to adjacent creatures by hand.", "info");
    if (confirm("Is your hero adjacent to the blast (takes 2 damage)?")) {
      h.hp -= 2; logMsg("Explodify splash: −2 HP to you.", "miss");
      if (h.hp <= 0) { h.hp = 0; return heroDies(), true; }
    }
  }
  return true;
}

// Vial of Acid: dissolve the lock on a chest (or a door, adjudicated). Returns true if used.
function useVialOfAcid() {
  const d = state.dungeon;
  const locked = (d.chests || []).filter((c) => !c.opened && c.status === "Locked");
  if (locked.length) {
    let c = locked[0];
    if (locked.length > 1) {
      const list = locked.map((x, i) => `${i + 1}. Locked chest (room ${x.roomNum})`).join("\n");
      const input = prompt(`Vial of Acid — open which locked chest?\n${list}\n\nEnter a number:`, "1");
      if (input === null) return false;
      const i = parseInt(input, 10) - 1;
      if (isNaN(i) || i < 0 || i >= locked.length) { toast("Invalid choice.", "err"); return false; }
      c = locked[i];
    }
    c.opened = true;
    logMsg(`Vial of Acid dissolves the lock on a chest (room ${c.roomNum}).`, "gold");
    rollTreasureItem();   // renders + saves
    return true;
  }
  if (confirm("No locked chest is tracked. Use the Vial of Acid on a locked door (adjudicate on your map)?")) {
    logMsg("Vial of Acid: dissolved a locked door's lock.", "gold");
    return true;
  }
  return false;   // nothing to open → don't waste it
}

