// to nudge the roll before committing. The effect is re-applied live from a snapshot.
function unstablePotion() {
  const h = state.hero;
  const snap = { str: h.str, agi: h.agi, wil: h.wil, maxhp: h.maxhp, hp: h.hp, maxap: h.maxap };
  let r = roll(6);
  const applyFromSnap = (val) => {
    Object.assign(h, snap);                              // reset to pre-potion baseline
    if (val === 1) h.str += 1;
    else if (val === 2) h.agi += 1;
    else if (val === 3) { h.wil += 1; }
    else if (val === 4) { h.maxhp += 3; h.hp += 3; }
    else if (val === 6) {                                // −1 to the highest attribute (from baseline)
