// Magical aspects that can be enchanted onto armor/shields (1 per 2 Bonus Rating).
const ASPECTS = [
  { name: "Bear's Might",        key: "str",      amt: 1, desc: "+1 Strength while equipped" },
  { name: "Cat's Nimbleness",    key: "agi",      amt: 1, desc: "+1 Agility while equipped" },
  { name: "Owl's Knowledge",     key: "wil",      amt: 1, desc: "+1 Willpower while equipped" },
  { name: "True Striking",       key: "hit",      amt: 1, desc: "+1 Hit to all combat rolls while equipped" },
  { name: "Mountain's Endurance", key: "maxhp",   amt: 3, desc: "+3 Max HP while equipped" },
  { name: "Youth's Vigor",       key: "maxap",    amt: 4, desc: "+4 Max AP while equipped" },
  { name: "Stag's Speed",        key: "movement", amt: 1, desc: "+1 Movement while equipped" },
];
// Sum of an aspect-key bonus across equipped armor + shield.
function aspectBonus(h, key) {
  let s = 0;
  ["armor", "shield"].forEach((slot) => {
    (h.equipped[slot]?.aspects || []).forEach((name) => {
      const a = ASPECTS.find((x) => x.name === name);
      if (a && a.key === key) s += a.amt;
    });
  });
  return s;
}
// Effective attributes (base + equipped aspect bonuses), used everywhere stats matter.
const effStr = (h) => h.str + aspectBonus(h, "str");
const effAgi = (h) => h.agi + aspectBonus(h, "agi");
const effWil = (h) => h.wil + aspectBonus(h, "wil");
const effMaxhp = (h) => h.maxhp + aspectBonus(h, "maxhp");
const effSkill = (h, skill) => ({ str: effStr, agi: effAgi, wil: effWil }[skill] || ((x) => x[skill]))(h);

function deriveMovement(h) { return ceilHalf(effAgi(h)) + wornBonus(h, "movement") + aspectBonus(h, "movement"); }
function deriveMaxAP(h) { return 2 * effWil(h) + wornBonus(h, "maxap") + aspectBonus(h, "maxap"); }

