// Choice modal for an armor/shield's Bonus Rating: +1 Armor per 3 BR, and/or one
// magical aspect per 2 BR (of the BR not spent on armor).
function allocateBR(item) {
  const budget = item.brBy || 0;
  let armorBonus = item.brA || 0;
  let aspects = [...(item.aspects || [])];
  const spent = () => armorBonus * 3 + aspects.length * 2;
  const remaining = () => budget - spent();
  const build = () => {
    const body = el("div", {},
      el("h2", {}, `Bonus Rating · ${item.name}`),
      el("div", { class: "note" }, `Spend this item's ${budget} Bonus Rating: +1 Armor per 3 BR, and/or one magical aspect per 2 BR (of the BR not spent on armor).`),
      el("div", { style: "text-align:center;margin:8px 0" },
        el("strong", { class: "br-bonus" }, `${remaining()} BR unspent`),
        el("span", { class: "sub" }, `   +${armorBonus} Armor · ${aspects.length} aspect${aspects.length === 1 ? "" : "s"}`)),
      el("div", { class: "btn-row", style: "align-items:center;gap:6px;margin:6px 0" },
        el("span", { class: "grow" }, `Armor bonus: `, el("strong", {}, `+${armorBonus}`)),
        el("button", { class: "btn sm", disabled: remaining() < 3 ? "" : null, onclick: () => { armorBonus++; refreshModal(build); } }, "+1 Armor (−3 BR)"),
        el("button", { class: "btn sm", disabled: armorBonus < 1 ? "" : null, onclick: () => { armorBonus--; refreshModal(build); } }, "−1")));
    aspects.forEach((name, i) => {
      const a = ASPECTS.find((x) => x.name === name);
      body.appendChild(el("div", { class: "btn-row", style: "align-items:center;gap:6px" },
        el("span", { class: "grow" }, el("span", { class: "br-bonus" }, `✦ ${name}`), el("span", { class: "sub" }, `  ${a ? a.desc : ""}`)),
        el("button", { class: "btn sm danger", onclick: () => { aspects.splice(i, 1); refreshModal(build); } }, "remove")));
    });
    if (remaining() >= 2) {
      const sel = el("select", { style: "margin-top:6px",
        onchange: (e) => { if (e.target.value) { aspects.push(e.target.value); refreshModal(build); } } });
      sel.appendChild(el("option", { value: "" }, "— add a magical aspect (−2 BR) —"));
      ASPECTS.filter((a) => !aspects.includes(a.name)).forEach((a) =>
        sel.appendChild(el("option", { value: a.name }, `${a.name} — ${a.desc}`)));
      body.appendChild(sel);
    }
    body.appendChild(el("div", { class: "btn-row", style: "justify-content:flex-end;gap:8px;margin-top:14px" },
      el("button", { class: "btn", onclick: closeModal }, "Cancel"),
      el("button", { class: "btn primary", onclick: () => {
        item.brA = armorBonus; item.aspects = aspects.slice();
        closeModal();
        logMsg(`${item.name} enchanted: +${armorBonus} Armor${aspects.length ? ", " + aspects.join(", ") : ""}.`, "gold");
        render(); saveNow();
      } }, "Save")));
    return body;
  };
  showModal(build);
}

