function allocateWeaponBR(item) {
  const budget = item.brBy || 0;
  let brD = item.brD || 0, brH = item.brH || 0;
  const remaining = () => budget - brD - brH;
  const row = (label, valTxt, plus, minus, canMinus) => el("div", { class: "btn-row", style: "align-items:center;gap:6px;margin:6px 0" },
    el("span", { class: "grow" }, label, "  ", el("strong", { class: "br-bonus" }, valTxt)),
    el("button", { class: "btn sm", disabled: remaining() < 1 ? "" : null, onclick: plus }, "+1"),
    el("button", { class: "btn sm", disabled: canMinus ? null : "", onclick: minus }, "−1"));
  const build = () => el("div", {},
    el("h2", {}, `Bonus Rating · ${item.name}`),
    el("div", { class: "note" }, `Spread this weapon's ${budget} Bonus Rating across Damage and/or Hit (1 BR each).`),
    el("div", { style: "text-align:center;margin:8px 0" }, el("strong", { class: "br-bonus" }, `${remaining()} BR unspent`)),
    row("Damage", `D${item.D}+${brD}`, () => { brD++; refreshModal(build); }, () => { brD--; refreshModal(build); }, brD > 0),
    row("Hit", `H${item.H}+${brH}`, () => { brH++; refreshModal(build); }, () => { brH--; refreshModal(build); }, brH > 0),
    el("div", { class: "btn-row", style: "justify-content:flex-end;gap:8px;margin-top:14px" },
      el("button", { class: "btn", onclick: closeModal }, "Cancel"),
      el("button", { class: "btn primary", onclick: () => {
        item.brD = brD; item.brH = brH;
        closeModal();
        logMsg(`${item.name} Bonus Rating: D+${brD}, H+${brH}.`, "gold");
        render(); saveNow();
      } }, "Save")));
  showModal(build);
}

