// Unspent Bonus Rating budget on a never-improved (but eligible) item, else 0.
function pendingBR(it) {
  const budget = it.brBy || 0;
  if (isWeaponItem(it)) return (budget >= 1 && (it.brD || 0) + (it.brH || 0) === 0) ? budget : 0;
  if (it.type === "armor" || it.type === "shield")
    return (budget >= 2 && (it.brA || 0) === 0 && !(it.aspects || []).length) ? budget : 0;
  return 0;
}

// Item stat line as DOM nodes; BR-improved stats are blue, un-allocated budget flagged.
function itemStatNodes(it) {
  const blue = (txt) => el("span", { class: "br-bonus", title: "improved by Bonus Rating" }, txt);
  const pend = pendingBR(it);
  const pendTag = () => pend ? el("span", { class: "br-pending-tag", title: "unallocated Bonus Rating — click ⚙ BR" }, `  ⚡${pend} BR`) : null;
  if (isWeaponItem(it)) {
    const nodes = [`R${it.R} `];
    nodes.push(it.brD ? blue(`D${it.D}+${it.brD}`) : `D${it.D}`);
    nodes.push(" ");
    nodes.push(it.brH ? blue(`H${it.H}+${it.brH}`) : `H${it.H}`);
    nodes.push(` ${it.hnd}Hnd ${skillName(it.skill)}`);
    if (pend) nodes.push(pendTag());
    return nodes;
  }
  if (it.type === "armor" || it.type === "shield") {
    const nodes = [it.brA ? blue(`${it.A || 0}+${it.brA}A`) : `${it.A || 0}A`];
    (it.aspects || []).forEach((name) => nodes.push(" ", blue(`✦${name}`)));
    if (pend) nodes.push(pendTag());
    return nodes;
  }
  return [it.text || ""];
}

// Build the ⚙ BR button — visually distinct (glowing) when there's unallocated budget.
function brButton(it, onclick) {
  const pend = pendingBR(it);
  return el("button", {
    class: "btn sm" + (pend ? " br-pending" : ""),
    title: pend ? `Allocate ${pend} unspent Bonus Rating` : "re-allocate Bonus Rating",
    onclick,
  }, pend ? `✨ ${pend} BR` : "⚙ BR");
}

