function allocateSpellBR(name) {
  const h = state.hero, s = G.spells.find((x) => x.name === name);
  const e = (h.spellBR || {})[name]; if (!e) return;
  const budget = e.brBy || 0;
  let brR = e.brR || 0, brD = e.brD || 0, brH = e.brH || 0;
  const remaining = () => budget - brR - brD - brH;
  const row = (label, valTxt, get, set) => el("div", { class: "btn-row", style: "align-items:center;gap:6px;margin:6px 0" },
    el("span", { class: "grow" }, label, "  ", el("strong", { class: "br-bonus" }, valTxt)),
    el("button", { class: "btn sm", disabled: remaining() < 1 ? "" : null, onclick: () => { set(get() + 1); refreshModal(build); } }, "+1"),
    el("button", { class: "btn sm", disabled: get() < 1 ? "" : null, onclick: () => { set(get() - 1); refreshModal(build); } }, "−1"));
  const build = () => el("div", {},
    el("h2", {}, `Bonus Rating · ${name}`),
    el("div", { class: "note" }, `Spread this spell's ${budget} Bonus Rating across Range, Damage and/or Hit (1 BR each). Range has no effect in-app (adjudicated), but is tracked.`),
    el("div", { style: "text-align:center;margin:8px 0" }, el("strong", { class: "br-bonus" }, `${remaining()} BR unspent`)),
    row("Range", `R${s.R}+${brR}`, () => brR, (v) => { brR = v; }),
    row("Damage", `D${s.D}+${brD}`, () => brD, (v) => { brD = v; }),
    row("Hit", `H${s.H}+${brH}`, () => brH, (v) => { brH = v; }),
