// Fireball blast: after the target is hit, deal the same damage to every other
// monster in or adjacent to the target's square (resolved from placed tokens).
function fireballSplash(target, dmg) {
  const r = state.dungeon.currentRoom;
  const tcell = r.tokens?.[target.uid];
  if (!tcell) { toast("Place tokens to auto-resolve Fireball's blast — apply it to nearby monsters by hand.", "info"); return; }
  const [tr, tc] = tcell.split(",").map(Number);
  const hit = r.monsters.filter((m) => {
    if (m.hp <= 0 || m === target) return false;
    const c = r.tokens?.[m.uid]; if (!c) return false;
    const [mr, mc] = c.split(",").map(Number);
    return Math.max(Math.abs(mr - tr), Math.abs(mc - tc)) <= 1;   // same square or adjacent (incl. diagonal)
  });
  if (!hit.length) return;
  logMsg(`Fireball blast: ${dmg} damage to ${hit.length} monster${hit.length === 1 ? "" : "s"} in/adjacent to ${target.label}'s square.`, "hit");
  hit.forEach((m) => applyDamageToMon(m, dmg));
}

