// Frost Bolt line: after the target is hit, deal the same damage to every other
// monster along the straight line from the hero through the target (range 4).
function frostBoltSplash(target, dmg) {
  const d = state.dungeon, r = d.currentRoom;
  const hero = d.map.hero, tcell = r.tokens?.[target.uid];
  if (!hero || !tcell) { toast("Place the hero + monster tokens to auto-resolve Frost Bolt's line — apply it by hand otherwise.", "info"); return; }
  const [hr, hc] = hero.split(",").map(Number);
  const [tr, tc] = tcell.split(",").map(Number);
  const dr = Math.sign(tr - hr), dc = Math.sign(tc - hc);
  if (dr === 0 && dc === 0) return;
  const onLine = (mr, mc) => {                              // same ray (orthogonal or diagonal), within range 4
    const er = mr - hr, ec = mc - hc;
    if (dr === 0) return er === 0 && Math.sign(ec) === dc && Math.abs(ec) > 0 && Math.abs(ec) <= 4;
    if (dc === 0) return ec === 0 && Math.sign(er) === dr && Math.abs(er) > 0 && Math.abs(er) <= 4;
    return Math.abs(er) === Math.abs(ec) && Math.sign(er) === dr && Math.sign(ec) === dc && Math.abs(er) <= 4;
  };
  const hit = r.monsters.filter((m) => {
    if (m.hp <= 0 || m === target) return false;
    const c = r.tokens?.[m.uid]; if (!c) return false;
    const [mr, mc] = c.split(",").map(Number);
    return onLine(mr, mc);
  });
  if (!hit.length) return;
  logMsg(`Frost Bolt line: ${dmg} damage to ${hit.length} more monster${hit.length === 1 ? "" : "s"} in the line.`, "hit");
  hit.forEach((m) => applyDamageToMon(m, dmg));
}

