// The rules don't tie a monster type to a room depth, so after a room is generated
// the player chooses which creature from the dungeon's package fills it.
function chooseRoomMonster(count, isBossRoom) {
  const d = state.dungeon, pkg = d.package.monsters;
  showModal(() => {
    const body = el("div", {}, el("h2", {}, `Room ${d.currentRoom.roomNum} — choose the monster`),
      el("div", { class: "note", style: "margin-bottom:8px" },
        (isBossRoom ? "Final room — defeat what's here to clear the dungeon. " : "") +
        `Roll: ${count} monster${count === 1 ? "" : "s"}. Pick which ${d.theme} creature fills this room.`));
    pkg.forEach((mn) => {
      const isBoss = /\(Boss\)/.test(mn.name);
      body.appendChild(el("button", { class: "btn", style: "display:block;width:100%;text-align:left;margin-bottom:6px",
        onclick: () => { closeModal(); populateRoom(mn, isBoss, count); } },
        el("strong", {}, baseName(mn.name) + (isBoss ? " 👑" : "")),
        el("span", { class: "sub" }, `  Def${mn.Def} HP${mn.HP} R${mn.R} M${mn.M} Att${mn.att[0]}-${mn.att[1]} D${mn.D}`),
        mn.special ? el("div", { class: "note", style: "margin:2px 0 0" }, mn.special) : null));
    });
    return body;
  });
}
// Spawn `count` of the chosen monster into the current room (applies the +2 # Monsters special).
function populateRoom(mon, boss, count) {
  const d = state.dungeon, r = d.currentRoom;
  if (!boss && mon.special && /\+2 to any # Monsters result of 1 or more/.test(mon.special) && count >= 1) count += 2;
  r.monsters = []; r.nextMonId = 0; r.tokens = {}; r.atkPenaltyAll = 0;
  r.monsterType = baseName(mon.name); r.monsterCount = count;
  for (let i = 0; i < count; i++) addMonsterInstance(r, mon, boss);
  relabelMonsters(r);
  d.inCombat = count > 0; d.round = count > 0 ? 1 : 0; d.mphase = null;
  logMsg(`${count} ${baseName(mon.name)}${count === 1 ? "" : "s"} fill the room.`, "gold");
  render(); saveNow();
}

