function openChestById(id) {
  const d = state.dungeon, h = state.hero;
  const c = (d.chests || []).find((x) => x.id === id);
  if (!c || c.opened) return;
  breakEtherealLink("opened a chest");
  if (c.status === "Locked" && !confirm("This chest is Locked. Open it anyway (assumes you used an ability/item/spell)?")) return;
  if (c.status === "Trapped") {
    if (!confirm("This chest is Trapped — opening it deals 1 HP that cannot be mitigated. Open it?")) return;
    h.hp -= 1; logMsg("Trapped chest! −1 HP (cannot be mitigated).", "miss");
    if (h.hp <= 0) { h.hp = 0; c.opened = true; render(); saveNow(); return heroDies(); }
  }
  if (c.status === "Unlocked") d.chests = d.chests.filter((x) => x.id !== id);   // looted → auto-remove
  else c.opened = true;                                                          // locked/trapped stay as opened
  logMsg(`Opened the ${c.status.toLowerCase()} chest (room ${c.roomNum}).`, "gold");
  rollTreasureItem();   // rolls treasure, then renders + saves
}
